sections.fragmentShader:
precision highp float;
varying vec2 v_texCoord;
uniform float u_time;
uniform float u_incoherence;
uniform float u_showLatency;

// Noise functions for procedural texture
float hash(vec2 p) {
    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    return mix(
        mix(hash(i), hash(i + vec2(1.0, 0.0)), f.x),
        mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), f.x),
        f.y
    );
}

float fbm(vec2 p) {
    float v = 0.0;
    float a = 0.5;
    for (int i = 0; i < 4; i++) {
        v += a * noise(p);
        p *= 2.0;
        a *= 0.5;
    }
    return v;
}

void main() {
    vec2 uv = v_texCoord;

    // Add incoherence: random UV offset per pixel
    vec2 offset = vec2(
        hash(gl_FragCoord.xy + u_time),
        hash(gl_FragCoord.yx - u_time)
    ) * u_incoherence * 0.5;

    vec2 sampleUV = uv + offset;

    // Simulate cache miss latency by temporal jitter
    float cacheMiss = step(0.5, hash(floor(sampleUV * 8.0) + floor(u_time * 10.0)));
    float latencyNoise = hash(gl_FragCoord.xy + u_time * 100.0);

    // Sample our 'texture' (procedural pattern)
    float pattern = fbm(sampleUV * 8.0);
    pattern += fbm(sampleUV * 16.0) * 0.5;

    // Apply simulated latency artifacts
    float latencyArtifact = cacheMiss * u_showLatency * latencyNoise * u_incoherence;
    pattern = mix(pattern, pattern * (1.0 - latencyArtifact * 0.5), u_showLatency);

    // Color based on cache efficiency
    vec3 coherentColor = vec3(0.18, 0.83, 0.75); // Teal
    vec3 missColor = vec3(0.91, 0.73, 0.14);     // Gold  
    vec3 color = mix(coherentColor, missColor, u_incoherence) * pattern;

    // Show 'stall' indicator
    if (u_showLatency > 0.5 && cacheMiss > 0.5 && u_incoherence > 0.3) {
        color = mix(color, vec3(0.8, 0.2, 0.1), latencyNoise * 0.3);
    }

    gl_FragColor = vec4(color, 1.0);
}
